#include<limits.h>
/*@
assigns \nothing;
ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 100
#define fun bor
#include <assert.h>
/*@
  requires \valid_read(x + (0 .. N - 1));
  assigns \nothing;
  ensures \forall integer k; 0 <= k < 32 ==>
            ((((((unsigned int)\result) >> k) & 1) == 1) <==>
             (\exists integer i; 0 <= i < N &&
                (((((unsigned int)x[i]) >> k) & 1) == 1)));
*/
int bor (int x[N])
{
  int i;
  long long res;
  res = x[0];
  /*@
    loop invariant 1 <= i <= N;
    loop invariant \forall integer k; 0 <= k < 32 ==>
                    ((((((unsigned int)res) >> k) & 1) == 1) <==>
                     (\exists integer j; 0 <= j < i &&
                        (((((unsigned int)x[j]) >> k) & 1) == 1)));
    loop assigns i, res;
    loop variant N - i;
  */
  for (i = 1; i < N; i++) {
    res = res | x[i];
  }
  return res;
}
int main ()
{
  int x[N];
  int temp;
  int ret;
  int ret2;
  int ret5;
  /*@
    loop invariant 0 <= i <= N;
    loop assigns i, x[0 .. N - 1];
    loop variant N - i;
  */
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  ret = fun(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = fun(x);
  temp=x[0];
  /*@
    loop invariant 0 <= i <= N - 1;
    loop invariant \forall integer k; 0 <= k < 32 ==>
      ( ( (\exists integer j; 0 <= j < N && (((((unsigned int)x[j]) >> k) & 1) == 1))
          || (((((unsigned int)temp) >> k) & 1) == 1) )
        <==>
        ( (\exists integer j; 0 <= j < N && (((((unsigned int)\at(x[j], LoopEntry)) >> k) & 1) == 1))
          || (((((unsigned int)temp) >> k) & 1) == 1) ) );
    loop invariant \forall integer j; 0 <= j < i ==> x[j] == \at(x[j+1], LoopEntry);
    loop invariant \forall integer j; i <= j < N ==> x[j] == \at(x[j], LoopEntry);
    loop assigns i, x[0 .. N - 2];
    loop variant N - 1 - i;
  */
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  //@ assert !(ret != ret2 || ret !=ret5);
  return 1;
}
